using Microsoft.Extensions.Logging;
using WAID.Application.Abstractions;
using WAID.Domain.Diagnostics;
using WAID.Domain.Repairs;

namespace WAID.Application.Services;

public enum RepairOrchestrationStage{Requested,Assessing,Assessed,Simulated,AwaitingApproval,Approved,Preparing,Executing,Validating,Committing,RollingBack,Committed,RolledBack,Failed,Cancelled,RecoveryRequired}
public enum RepairStepStatus{Pending,Running,Succeeded,Failed,Skipped}
public sealed record RepairOrchestrationStep(int Order,RepairOrchestrationStage Stage,string Title,RepairStepStatus Status,DateTimeOffset? StartedAtUtc,DateTimeOffset? CompletedAtUtc,string Detail);
public sealed record RepairSimulation(string Description,IReadOnlyList<string> Actions,IReadOnlyList<RepairResource> Resources,SafetyLevel Risk,bool RequiresAdministrator,bool RequiresRestorePoint,bool RequiresBackup,bool SupportsRollback,IReadOnlyList<string> Dependencies,IReadOnlyList<string> Conflicts,string SimulationVersion,string Fingerprint,DateTimeOffset SimulatedAtUtc,DateTimeOffset ValidUntilUtc,IReadOnlyList<RepairPredictedEffect> Effects,IReadOnlyList<string> Assumptions,IReadOnlyList<string> Warnings,TimeSpan? EstimatedDuration,long? EstimatedSpaceBytes,bool? PredictedRestartRequired,RepairSafetyAssessment? SafetyAssessment=null);
public sealed record RepairValidationOutcome(bool Succeeded,string ValidatorVersion,DateTimeOffset ValidatedAtUtc,string Summary,IReadOnlyList<string> Evidence);
public sealed record RepairApprovalDecision(bool Approved,bool RiskAcknowledged,DateTimeOffset DecidedAtUtc,string Actor,string PolicyVersion,RepairApprovalType ApprovalType=RepairApprovalType.Explicit);
public sealed record RepairOrchestrationRecord(Guid Id,string RepairId,DateTimeOffset CreatedAtUtc,DateTimeOffset UpdatedAtUtc,RepairOrchestrationStage Stage,string LifecycleVersion,RepairSimulation? Simulation,RepairApprovalDecision? Approval,Guid? TransactionId,RepairTransactionStatus? TransactionStatus,string? BackupLocation,string? RestorePointDescription,bool RestartRequired,RepairValidationOutcome? Validation,IReadOnlyList<RepairOrchestrationStep> Steps,string Outcome,RepairWorkflowUiState? UiState=null);
public sealed record RepairOrchestrationRequest(string RepairId,DiagnosticFinding? Finding,IReadOnlySet<string> SatisfiedDependencies,IReadOnlySet<string> ActiveRepairIds);
public sealed record RepairProgress(Guid OrchestrationId,RepairOrchestrationStage Stage,int CompletedSteps,int TotalSteps,string Detail,double Percentage);
public enum RepairWorkflowScreen{PlanReview,Evidence,Simulation,Approval,Progress,Restart,Validation,Rollback,Report,Recovery}
public sealed record RepairWorkflowUiState(RepairWorkflowScreen Screen,string CurrentAction,string PlainSummary,string TechnicalSummary,bool CanExecute,bool CanCancel,DateTimeOffset UpdatedAtUtc);
public sealed record RepairOrchestrationOptions(TimeSpan ExecutionTimeout){public static RepairOrchestrationOptions Default{get;}=new(TimeSpan.FromMinutes(30));public RepairOrchestrationOptions Validate()=>ExecutionTimeout<TimeSpan.FromMinutes(1)||ExecutionTimeout>TimeSpan.FromHours(2)?throw new InvalidOperationException("Repair execution timeout must be between one minute and two hours."):this;}

public static class RepairLifecycleStateMachine
{
 private static readonly IReadOnlyDictionary<RepairOrchestrationStage,IReadOnlySet<RepairOrchestrationStage>> Allowed=new Dictionary<RepairOrchestrationStage,IReadOnlySet<RepairOrchestrationStage>>
 {
  [RepairOrchestrationStage.Requested]=Set(RepairOrchestrationStage.Assessing,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.Assessing]=Set(RepairOrchestrationStage.Assessed,RepairOrchestrationStage.Failed,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.Assessed]=Set(RepairOrchestrationStage.Simulated,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.Simulated]=Set(RepairOrchestrationStage.AwaitingApproval,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.AwaitingApproval]=Set(RepairOrchestrationStage.Approved,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.Approved]=Set(RepairOrchestrationStage.Preparing,RepairOrchestrationStage.Cancelled),
  [RepairOrchestrationStage.Preparing]=Set(RepairOrchestrationStage.Executing,RepairOrchestrationStage.Failed,RepairOrchestrationStage.Cancelled,RepairOrchestrationStage.RecoveryRequired),
  [RepairOrchestrationStage.Executing]=Set(RepairOrchestrationStage.Validating,RepairOrchestrationStage.RollingBack,RepairOrchestrationStage.Failed,RepairOrchestrationStage.Cancelled,RepairOrchestrationStage.RecoveryRequired),
  [RepairOrchestrationStage.Validating]=Set(RepairOrchestrationStage.Committing,RepairOrchestrationStage.RollingBack,RepairOrchestrationStage.Failed,RepairOrchestrationStage.Cancelled,RepairOrchestrationStage.RecoveryRequired),
  [RepairOrchestrationStage.Committing]=Set(RepairOrchestrationStage.Committed,RepairOrchestrationStage.RecoveryRequired),
  [RepairOrchestrationStage.RollingBack]=Set(RepairOrchestrationStage.RolledBack,RepairOrchestrationStage.Failed,RepairOrchestrationStage.RecoveryRequired)
 };
 public static void EnsureTransition(RepairOrchestrationStage from,RepairOrchestrationStage to){if(from==to)return;if(to==RepairOrchestrationStage.Cancelled&&from is not(RepairOrchestrationStage.Committed or RepairOrchestrationStage.RolledBack or RepairOrchestrationStage.Failed or RepairOrchestrationStage.RecoveryRequired))return;if(!Allowed.TryGetValue(from,out var allowed)||!allowed.Contains(to))throw new InvalidOperationException($"Repair lifecycle cannot transition from {from} to {to}.");}
 private static IReadOnlySet<RepairOrchestrationStage>Set(params RepairOrchestrationStage[] stages)=>new HashSet<RepairOrchestrationStage>(stages);
}
public sealed class RepairOrchestrationException(string code,string message,string recoveryAction):InvalidOperationException(message){public string Code{get;}=code;public string RecoveryAction{get;}=recoveryAction;}
public interface IRepairOrchestrationRepository{Task SaveAsync(RepairOrchestrationRecord record,CancellationToken token);Task<RepairOrchestrationRecord?> GetAsync(Guid id,CancellationToken token);Task<IReadOnlyList<RepairOrchestrationRecord>> GetRecentAsync(int count,CancellationToken token);Task<IReadOnlyList<RepairOrchestrationRecord>> GetNonTerminalAsync(CancellationToken token);}
public interface IRepairValidator{string Version{get;}Task<RepairValidationOutcome> ValidateAsync(IRepairModule module,RepairTransaction transaction,CancellationToken token);}
public interface IRepairDependencyCatalog{IReadOnlyList<string> DependenciesFor(string repairId);IReadOnlyList<string> ConflictsFor(string repairId);}
public sealed class EmptyRepairDependencyCatalog:IRepairDependencyCatalog{public IReadOnlyList<string>DependenciesFor(string repairId)=>[];public IReadOnlyList<string>ConflictsFor(string repairId)=>[];}
public sealed class DefaultRepairValidator(TimeProvider time):IRepairValidator
{
 public string Version=>"repair-validation-1.0";
 public Task<RepairValidationOutcome>ValidateAsync(IRepairModule module,RepairTransaction transaction,CancellationToken token){token.ThrowIfCancellationRequested();var succeeded=transaction.Status==RepairTransactionStatus.Succeeded&&transaction.Result?.Succeeded==true;var evidence=new List<string>{$"Transaction status: {transaction.Status}",$"Repair result present: {transaction.Result is not null}"};if(transaction.Result?.RestartRequired==true)evidence.Add("Validation is provisional until Windows restarts.");return Task.FromResult(new RepairValidationOutcome(succeeded,Version,time.GetUtcNow(),succeeded?"Execution completed and returned a successful typed result.":"Execution did not return a successful result.",evidence));}
}

public sealed class RepairOrchestrator(RepairRegistry registry,RepairExecutor executor,IRepairOrchestrationRepository repository,IRepairValidator validator,IRepairDependencyCatalog dependencies,TimeProvider time,ILogger<RepairOrchestrator> logger,IAuditTrailService? audit=null,RepairOrchestrationOptions? options=null,IRepairSimulationEngine? simulationEngine=null,IRepairSafetyScorer? safetyScorer=null,RepairSafetyPolicy? safetyPolicy=null,IRepairOutcomeRecorder? outcomes=null)
{
 public const string LifecycleVersion="repair-lifecycle-1.0";private readonly SemaphoreSlim _gate=new(1,1);private readonly RepairOrchestrationOptions _options=(options??RepairOrchestrationOptions.Default).Validate();private readonly IRepairSimulationEngine _simulationEngine=simulationEngine??new DeterministicRepairSimulationEngine(time);private readonly IRepairSafetyScorer _safetyScorer=safetyScorer??new DeterministicRepairSafetyScorer();private readonly RepairSafetyPolicy _safetyPolicy=(safetyPolicy??RepairSafetyPolicy.Default).Validate();
 public async Task<RepairOrchestrationRecord> AssessAndSimulateAsync(RepairOrchestrationRequest request,IProgress<RepairProgress>? progress,CancellationToken token)
 {
  if(!registry.TryGet(request.RepairId,out var module)||module is null)throw new RepairOrchestrationException("WAID-REPAIR-NOT-REGISTERED","The requested repair is unavailable.","Refresh recommendations and select a registered repair.");module.Policy.Validate();var now=time.GetUtcNow();var record=new RepairOrchestrationRecord(Guid.NewGuid(),module.Id,now,now,RepairOrchestrationStage.Requested,LifecycleVersion,null,null,null,null,null,null,false,null,Steps(),"Assessment requested.");await Save(record,progress,token);
  record=Move(record,RepairOrchestrationStage.Assessing,"Assessing repair definition.");await Save(record,progress,token);var plan=await module.CreatePlanAsync(request.Finding,token).ConfigureAwait(false);if(string.IsNullOrWhiteSpace(plan.Description)||plan.Description.Length>2000)throw new RepairOrchestrationException("WAID-REPAIR-PLAN-INVALID","The repair returned an invalid plan.","Do not run this repair; review Logs & Audit.");foreach(var resource in plan.Resources)resource.Validate();var required=dependencies.DependenciesFor(module.Id);var conflicts=dependencies.ConflictsFor(module.Id);var missing=required.Where(x=>!request.SatisfiedDependencies.Contains(x)).ToArray();var active=conflicts.Where(request.ActiveRepairIds.Contains).ToArray();if(missing.Length>0||active.Length>0){record=Move(record,RepairOrchestrationStage.Failed,$"Blocked: missing dependencies [{string.Join(", ",missing)}]; conflicts [{string.Join(", ",active)}].",true);await Save(record,progress,token);await Audit(record,AuditResult.Rejected,record.Outcome,token);return record;}
  record=Move(record,RepairOrchestrationStage.Assessed,"Repair definition, policy, dependencies, conflicts, and resources validated.");await Save(record,progress,token);var simulation=_simulationEngine.Create(module,plan,required,conflicts);simulation=simulation with{SafetyAssessment=_safetyScorer.Evaluate(module.Id,simulation,_safetyPolicy)};record=Move(record with{Simulation=simulation},RepairOrchestrationStage.Simulated,"Versioned dry run completed; no commands ran and no system state changed.");await Save(record,progress,token);record=Move(record,RepairOrchestrationStage.AwaitingApproval,"Explicit user approval is required.");await Save(record,progress,token);await Audit(record,AuditResult.Requested,$"Repair simulation {simulation.SimulationVersion} recorded with fingerprint {simulation.Fingerprint[..12]}; safety {simulation.SafetyAssessment!.Score}/100, approval {simulation.SafetyAssessment.RequiredApproval}, policy {simulation.SafetyAssessment.PolicyResult}; awaiting approval.",token);return record;
 }
 public async Task<RepairOrchestrationRecord> ExecuteAsync(Guid id,bool approved,bool riskAcknowledged,IProgress<RepairProgress>? progress,CancellationToken token)
 {
  if(!await _gate.WaitAsync(0,token).ConfigureAwait(false))throw new RepairOrchestrationException("WAID-REPAIR-CONCURRENT","Another repair orchestration is active.","Wait for the active repair to finish or cancel it safely.");try{var record=await repository.GetAsync(id,token).ConfigureAwait(false)??throw new RepairOrchestrationException("WAID-REPAIR-PLAN-MISSING","The repair plan no longer exists.","Assess and simulate the repair again.");if(record.Stage!=RepairOrchestrationStage.AwaitingApproval||record.Simulation is null)throw new RepairOrchestrationException("WAID-REPAIR-STATE","The repair is not awaiting approval.","Refresh the repair plan and review its current state.");if(!registry.TryGet(record.RepairId,out var currentModule)||currentModule is null)throw new RepairOrchestrationException("WAID-REPAIR-NOT-REGISTERED","The simulated repair is no longer registered.","Refresh repairs and create a new simulation.");var currentPlan=await currentModule.CreatePlanAsync(null,token).ConfigureAwait(false);var currentDependencies=dependencies.DependenciesFor(record.RepairId);var currentConflicts=dependencies.ConflictsFor(record.RepairId);if(!_simulationEngine.IsCurrent(record.Simulation,currentModule,currentPlan,currentDependencies,currentConflicts)){record=Move(record,RepairOrchestrationStage.Cancelled,"The dry run is stale because its version, expiry, repair definition, policy, resources, prerequisites, conflicts, or predicted effects changed. Simulate again before approval.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Rejected,record.Outcome,CancellationToken.None);return record;}var currentSafety=_safetyScorer.Evaluate(record.RepairId,record.Simulation,_safetyPolicy);var storedSafety=record.Simulation.SafetyAssessment;if(storedSafety is null||storedSafety.ScoringVersion!=currentSafety.ScoringVersion||storedSafety.PolicyVersion!=currentSafety.PolicyVersion||storedSafety.Score!=currentSafety.Score||storedSafety.RequiredApproval!=currentSafety.RequiredApproval||storedSafety.PolicyResult!=currentSafety.PolicyResult){record=Move(record,RepairOrchestrationStage.Cancelled,"The safety score or active policy changed. Simulate and review the repair again.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Rejected,record.Outcome,CancellationToken.None);return record;}if(currentSafety.PolicyResult==RepairPolicyResult.Blocked){record=Move(record,RepairOrchestrationStage.Cancelled,$"Repair blocked by policy: {string.Join(" ",currentSafety.PolicyRequirements)}",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Rejected,record.Outcome,CancellationToken.None);return record;}var requiresRisk=currentSafety.RequiredApproval>=RepairApprovalType.ExplicitWithRiskAcknowledgement;if(!approved||requiresRisk&&!riskAcknowledged){record=Move(record with{Approval=new(approved,riskAcknowledged,time.GetUtcNow(),"User",LifecycleVersion,currentSafety.RequiredApproval)},RepairOrchestrationStage.Cancelled,!approved?"User declined the repair.":$"Required {currentSafety.RequiredApproval} confirmation was not provided.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Rejected,record.Outcome,CancellationToken.None);return record;}record=Move(record with{Approval=new(true,riskAcknowledged,time.GetUtcNow(),"User",LifecycleVersion,currentSafety.RequiredApproval)},RepairOrchestrationStage.Approved,"Explicit approval recorded for the current dry run.");await Save(record,progress,token);await Audit(record,AuditResult.Approved,$"Explicit repair approval recorded; safety {currentSafety.Score}/100, type {currentSafety.RequiredApproval}, policy {currentSafety.PolicyResult}.",token);record=Move(record,RepairOrchestrationStage.Preparing,"Safety preparation delegated to the central repair executor.");await Save(record,progress,token);record=Move(record,RepairOrchestrationStage.Executing,"Repair execution started.");await Save(record,progress,token);
   RepairTransaction transaction;using var execution=CancellationTokenSource.CreateLinkedTokenSource(token);execution.CancelAfter(_options.ExecutionTimeout);try{transaction=await executor.ExecuteAsync(record.RepairId,null,true,execution.Token).ConfigureAwait(false);}catch(OperationCanceledException)when(execution.IsCancellationRequested){var userCancelled=token.IsCancellationRequested;record=Move(record,userCancelled?RepairOrchestrationStage.Cancelled:RepairOrchestrationStage.RecoveryRequired,userCancelled?"Repair cancellation was requested; executor recovery and rollback policy completed.":$"Repair exceeded the {_options.ExecutionTimeout.TotalMinutes:0}-minute execution timeout. Automatic retry is forbidden; inspect repair and rollback history.",true);await Save(record,progress,CancellationToken.None);await Audit(record,userCancelled?AuditResult.Cancelled:AuditResult.Failed,record.Outcome,CancellationToken.None);if(userCancelled)throw;return record;}
   record=record with{TransactionId=transaction.Id,TransactionStatus=transaction.Status,BackupLocation=SafePath(transaction.BackupLocation),RestorePointDescription=transaction.RestorePointDescription,RestartRequired=transaction.Result?.RestartRequired??false};if(transaction.Status==RepairTransactionStatus.RolledBack){record=Move(record,RepairOrchestrationStage.RollingBack,"Executor rolled back the unsuccessful repair.");await Save(record,progress,CancellationToken.None);record=Move(record,RepairOrchestrationStage.RolledBack,"Repair failed and rollback completed.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.RolledBack,record.Outcome,CancellationToken.None);return record;}if(transaction.Status!=RepairTransactionStatus.Succeeded){record=Move(record,RepairOrchestrationStage.Failed,transaction.Result?.Summary??$"Repair ended with {transaction.Status}.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Failed,record.Outcome,CancellationToken.None);return record;}
   record=Move(record,RepairOrchestrationStage.Validating,"Post-execution validation started.");await Save(record,progress,token);var validation=await validator.ValidateAsync(registry.All.Single(x=>x.Id.Equals(record.RepairId,StringComparison.OrdinalIgnoreCase)),transaction,token).ConfigureAwait(false);record=record with{Validation=validation};if(!validation.Succeeded){record=Move(record,RepairOrchestrationStage.RecoveryRequired,"Validation failed after execution. Do not rerun automatically; inspect backup and repair history.",true);await Save(record,progress,CancellationToken.None);await Audit(record,AuditResult.Failed,record.Outcome,CancellationToken.None);return record;}record=Move(record,RepairOrchestrationStage.Committing,"Validation passed; committing orchestration outcome.");await Save(record,progress,token);record=Move(record,RepairOrchestrationStage.Committed,record.RestartRequired?"Repair validated provisionally; restart is required to complete verification.":"Repair executed and validated successfully.",true);await Save(record,progress,token);await Audit(record,AuditResult.Succeeded,record.Outcome,CancellationToken.None);return record;
  }finally{_gate.Release();}
 }
 public async Task<RepairOrchestrationRecord> CancelAsync(Guid id,CancellationToken token){var record=await repository.GetAsync(id,token).ConfigureAwait(false)??throw new RepairOrchestrationException("WAID-REPAIR-NOTFOUND","Repair lifecycle was not found.","Refresh repair history and create a new plan.");if(record.Stage is RepairOrchestrationStage.Committed or RepairOrchestrationStage.RolledBack or RepairOrchestrationStage.Failed or RepairOrchestrationStage.Cancelled or RepairOrchestrationStage.RecoveryRequired)return record;if(record.Stage is RepairOrchestrationStage.Executing or RepairOrchestrationStage.Validating or RepairOrchestrationStage.Committing or RepairOrchestrationStage.RollingBack)throw new RepairOrchestrationException("WAID-REPAIR-CANCEL-ACTIVE","Use cooperative cancellation for an active repair.","Wait for the cancellation outcome and review recovery state.");var cancelled=Move(record,RepairOrchestrationStage.Cancelled,"Repair plan cancelled by the user before execution. No changes were made.",true);await Save(cancelled,null,token);await Audit(cancelled,AuditResult.Cancelled,cancelled.Outcome,token);return cancelled;}
 public async Task<IReadOnlyList<RepairOrchestrationRecord>> RecoverInterruptedAsync(CancellationToken token){var recovered=new List<RepairOrchestrationRecord>();foreach(var record in await repository.GetNonTerminalAsync(token).ConfigureAwait(false)){if(record.Stage==RepairOrchestrationStage.AwaitingApproval&&record.Simulation is not null){var resumed=record with{UpdatedAtUtc=time.GetUtcNow(),Outcome="Reviewed repair plan restored after restart. Recheck the current action and approve explicitly to continue.",UiState=Present(record,RepairOrchestrationStage.AwaitingApproval,"Review the restored plan and choose Approve or Cancel.",time.GetUtcNow())};await Save(resumed,null,token);await Audit(resumed,AuditResult.Requested,"Safe pre-execution workflow resumed; no repair action was repeated.",token);recovered.Add(resumed);continue;}var dangerous=record.Stage is RepairOrchestrationStage.Executing or RepairOrchestrationStage.Validating or RepairOrchestrationStage.Committing or RepairOrchestrationStage.RollingBack;var updated=Move(record,dangerous?RepairOrchestrationStage.RecoveryRequired:RepairOrchestrationStage.Cancelled,dangerous?"Application restarted during or after execution. Automatic rerun is forbidden; inspect repair history, backup, validation, and rollback state.":"Application restarted before execution; the incomplete workflow was cancelled without making changes.",true);await Save(updated,null,token);await Audit(updated,dangerous?AuditResult.Failed:AuditResult.Cancelled,updated.Outcome,token);recovered.Add(updated);}return recovered;}
 private static IReadOnlyList<RepairOrchestrationStep>Steps()=>Enum.GetValues<RepairOrchestrationStage>().Where(x=>x is not(RepairOrchestrationStage.Requested or RepairOrchestrationStage.RecoveryRequired)).Select((x,i)=>new RepairOrchestrationStep(i+1,x,x.ToString(),RepairStepStatus.Pending,null,null,"Pending.")).ToArray();
 private RepairOrchestrationRecord Move(RepairOrchestrationRecord record,RepairOrchestrationStage stage,string detail,bool terminal=false){RepairLifecycleStateMachine.EnsureTransition(record.Stage,stage);var now=time.GetUtcNow();var steps=record.Steps.Select(x=>x.Stage==stage?x with{Status=stage is RepairOrchestrationStage.Failed or RepairOrchestrationStage.Cancelled or RepairOrchestrationStage.RecoveryRequired?RepairStepStatus.Failed:RepairStepStatus.Succeeded,StartedAtUtc=x.StartedAtUtc??now,CompletedAtUtc=now,Detail=detail}:x).ToArray();return record with{Stage=stage,UpdatedAtUtc=now,Steps=steps,Outcome=detail,UiState=Present(record,stage,detail,now)};}
 private static RepairWorkflowUiState Present(RepairOrchestrationRecord record,RepairOrchestrationStage stage,string detail,DateTimeOffset now){var screen=stage switch{RepairOrchestrationStage.Requested or RepairOrchestrationStage.Assessing or RepairOrchestrationStage.Assessed=>RepairWorkflowScreen.PlanReview,RepairOrchestrationStage.Simulated=>RepairWorkflowScreen.Simulation,RepairOrchestrationStage.AwaitingApproval or RepairOrchestrationStage.Approved=>RepairWorkflowScreen.Approval,RepairOrchestrationStage.Preparing or RepairOrchestrationStage.Executing=>RepairWorkflowScreen.Progress,RepairOrchestrationStage.Validating=>RepairWorkflowScreen.Validation,RepairOrchestrationStage.RollingBack or RepairOrchestrationStage.RolledBack=>RepairWorkflowScreen.Rollback,RepairOrchestrationStage.RecoveryRequired=>RepairWorkflowScreen.Recovery,_=>RepairWorkflowScreen.Report};var action=stage switch{RepairOrchestrationStage.AwaitingApproval=>"Review evidence, simulation, safety score, and safeguards; then approve or cancel.",RepairOrchestrationStage.Executing=>"Wait while the approved repair runs. You may request cancellation.",RepairOrchestrationStage.Validating=>"Wait while WAID validates the repair outcome.",RepairOrchestrationStage.RecoveryRequired=>"Do not rerun. Review recovery artifacts and the recorded backend state.",RepairOrchestrationStage.Committed when record.RestartRequired=>"Save work and restart Windows, then verify the result.",_=>detail};var technical=$"Stage {stage}; lifecycle {record.LifecycleVersion}; transaction {(record.TransactionId?.ToString("N")??"not assigned")}.";return new(screen,action,detail,technical,stage==RepairOrchestrationStage.AwaitingApproval,stage is RepairOrchestrationStage.Assessing or RepairOrchestrationStage.AwaitingApproval or RepairOrchestrationStage.Preparing or RepairOrchestrationStage.Executing or RepairOrchestrationStage.Validating,now);}
 private async Task Save(RepairOrchestrationRecord record,IProgress<RepairProgress>? progress,CancellationToken token){await repository.SaveAsync(record,token).ConfigureAwait(false);if(outcomes is not null)await outcomes.RecordAsync(record,token).ConfigureAwait(false);var complete=record.Steps.Count(x=>x.Status is RepairStepStatus.Succeeded or RepairStepStatus.Failed or RepairStepStatus.Skipped);progress?.Report(new(record.Id,record.Stage,complete,record.Steps.Count,record.Outcome,record.Steps.Count==0?0:complete*100d/record.Steps.Count));logger.LogInformation("Repair orchestration {OrchestrationId} entered {Stage}",record.Id,record.Stage);}
 private async Task Audit(RepairOrchestrationRecord record,AuditResult result,string detail,CancellationToken token){if(audit is null)return;try{await audit.AppendAsync(new(Guid.NewGuid(),time.GetUtcNow(),AuditActor.User,"RepairOrchestration",record.RepairId,result,record.Simulation?.Risk??SafetyLevel.Low,record.Simulation?.RequiresAdministrator??false,record.Simulation?.SupportsRollback??false,record.Id,record.Id,detail),token).ConfigureAwait(false);}catch(Exception e)when(e is not OperationCanceledException){logger.LogWarning("Repair orchestration audit failed with {FailureType}",e.GetType().Name);}}
 private static string? SafePath(string? value){if(string.IsNullOrWhiteSpace(value))return value;var profile=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);return string.IsNullOrWhiteSpace(profile)?value:value.Replace(profile,"%USERPROFILE%",StringComparison.OrdinalIgnoreCase);}
}
